create table if not exists archetype_pending (
    owner integer primary key, prior integer
  );
  create table if not exists archetype_delta (
    owner integer, name text, present integer, primary key(owner, name)
  );
  create trigger if not exists archetype_birth after insert on entity begin
    insert or ignore into archetype_pending(owner, prior) values (new.id, null);
  end;

create trigger if not exists "archetype_about_insert"
        after insert on "about" begin
        insert or ignore into archetype_pending(owner, prior)
          select id, archetype from entity where id = new.entity;
        insert into archetype_delta(owner, name, present)
          values (new.entity, 'about', 1)
          on conflict(owner, name) do update set present = excluded.present;
        update entity set archetype = null where id = new.entity;
      end;

create trigger if not exists "archetype_about_delete"
        after delete on "about" begin
        insert or ignore into archetype_pending(owner, prior)
          select id, archetype from entity where id = old.entity;
        insert into archetype_delta(owner, name, present)
          values (old.entity, 'about', 0)
          on conflict(owner, name) do update set present = excluded.present;
        update entity set archetype = null where id = old.entity;
      end;

